class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        ans = -1
        for i in range(n - 1):
            if nums[i + 1] - nums[i] != 1:
                continue
            j = i + 1
            while j + 1 < n and nums[j + 1] - nums[j] == (1 if (j - i) % 2 == 0 else -1):
                j += 1
            ans = max(ans, j - i + 1)
        return ans

