class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        ans, cur, exp = -1, 0, 1
        for i in range(n - 1):
            d = nums[i + 1] - nums[i]
            if d == exp:
                cur = 2 if cur == 0 else cur + 1
                exp = -exp
            else:
                cur = 2 if d == 1 else 0
                exp = -1 if d == 1 else 1
            ans = max(ans, cur)
        return ans if ans >= 2 else -1

